#!/usr/bin/env bash
set -euo pipefail

# Generated by RoleCraft — https://rolecraft.omhinge.cloud
# Creates an IAM role with its trust policy and permissions.

ROLE_NAME='audit-reader'

# Trust policy: who can assume the role
cat > trust.json <<'ROLECRAFT_EOF'
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {
        "AWS": "arn:aws:iam::210987654321:root"
      },
      "Action": "sts:AssumeRole",
      "Condition": {
        "StringEquals": {
          "sts:ExternalId": "rolecraft-ext-01"
        },
        "Bool": {
          "aws:MultiFactorAuthPresent": "true"
        }
      }
    }
  ]
}
ROLECRAFT_EOF

# Permissions policy
cat > policy.json <<'ROLECRAFT_EOF'
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "TextractReadAll",
      "Effect": "Allow",
      "Action": [
        "textract:AnalyzeDocument",
        "textract:AnalyzeExpense",
        "textract:AnalyzeID",
        "textract:DetectDocumentText",
        "textract:GetAdapter",
        "textract:GetAdapterVersion",
        "textract:GetDocumentAnalysis",
        "textract:GetDocumentTextDetection",
        "textract:GetExpenseAnalysis",
        "textract:GetLendingAnalysis",
        "textract:GetLendingAnalysisSummary",
        "textract:ListAdapterVersions",
        "textract:ListAdapters",
        "textract:ListTagsForResource"
      ],
      "Resource": "*"
    }
  ]
}
ROLECRAFT_EOF

aws iam create-role --role-name "$ROLE_NAME" --assume-role-policy-document file://trust.json --description 'Created with RoleCraft'
POLICY_ARN=$(aws iam create-policy --policy-name "${ROLE_NAME}-policy" --policy-document file://policy.json --query Policy.Arn --output text)
aws iam attach-role-policy --role-name "$ROLE_NAME" --policy-arn "$POLICY_ARN"

echo "Created role $ROLE_NAME."
echo "Created and attached policy ${ROLE_NAME}-policy."
